import itertools
from collections import defaultdict
import time
from FPgrowth import fp_growth
import sys

# 定义函数生成所有子集，按长度递减顺序
def generate_subsets(lst):
    for i in range(len(lst), 0, -1):
        for subset in itertools.combinations(lst, i):
            yield subset

def intersection(dataset):
    intersection = set(dataset[0])
    for lst in dataset[1:]:
        lst.sort()
        intersection &= set(lst)
    return intersection

def a(dataset):
    # 创建一个字典记录子集出现的次数
    subset_counts = defaultdict(int)
    print(dataset)

    # 统计每个子集的出现次数
    for lst in dataset:
        subsets = generate_subsets(lst)
        for subset in subsets:
            subset_counts[subset] += 1

    # 移除那些出现次数相同且长度较短的子集
    filtered_subsets = {}
    for subset, count in sorted(subset_counts.items(), key=lambda x: len(x[0]), reverse=True):
        if not any(set(subset).issubset(set(other_subset)) and count == subset_counts[other_subset]
                   for other_subset in filtered_subsets):
            filtered_subsets[subset] = count

    return filtered_subsets
    # 按子集长度递减顺序打印子集出现的次数
    # for length in range(max(map(len, dataset)), 0, -1):
    #     for subset, count in filtered_subsets.items():
    #         if len(subset) == length:
    #             print(f"{subset}: {count}")
def create_node_dict(dataset):
    # 计算所有列表的交集
    intersect = intersection(dataset)
    # # 从每个列表中删除存在于交集中的元素
    # filtered_dataset = [[element for element in lst if element not in intersect] for lst in dataset]
    # 从每个列表中删除存在于交集中的元素，且删除后空列表不存储
    filtered_dataset = [lst for lst in [[element for element in lst if element not in intersect] for lst in dataset] if lst]
    if filtered_dataset:
        # print(filtered_dataset)
        filtered_subsets = fp_growth(filtered_dataset)
        node_dict = {}
        for subset, count in filtered_subsets.items():
            node = set(subset) | intersect
            node_dict[tuple(node)] = count
        node_dict[tuple(intersect)] = int(len(dataset))
    else:
        node_dict = {tuple(intersect): int(len(dataset))}

    return node_dict, tuple(intersect)

